// Generated by AI
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    [Header("Movement Settings")]
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpForce = 8f;

    [Header("Jump Settings")]
    [SerializeField] private int maxJumps = 2;
    [SerializeField] private LayerMask groundLayer;
    [SerializeField] private Transform groundCheck;
    [SerializeField] private float groundCheckRadius = 0.2f;

    [Header("Audio Settings")]
    [SerializeField] private AudioClip jumpClip;
    [SerializeField] private AudioClip crouchClip;
    [SerializeField] private AudioClip pickupClip;

    [Header("Coyote Time")]
    [SerializeField] private float coyoteTime = 0.15f;

    private AudioSource audioSource;
    private Rigidbody2D rb;
    private Animator animator;
    private SpriteRenderer spriteRenderer;
    private int jumpCount = 0;
    private bool isGrounded;
    private float coyoteTimer;
    private float moveInput;

    // Tracks whether movement is being controlled through the HUD.
    private bool usingHUD = false;

    private void Start()
    {
        rb = GetComponent<Rigidbody2D>();
        audioSource = GetComponent<AudioSource>();
        animator = GetComponent<Animator>();
        spriteRenderer = GetComponent<SpriteRenderer>();
    }

    private void Update()
    {
        if (!PauseMenuController.GameStarted)
            return;

        isGrounded = Physics2D.OverlapCircle(
        groundCheck.position,
        groundCheckRadius,
        groundLayer
        );

        if (isGrounded)
        {
            coyoteTimer = coyoteTime;
            jumpCount = 0;
        }
        else
        {
            coyoteTimer -= Time.deltaTime;
        }

        // Read keyboard input only when HUD controls are inactive.
        if (!usingHUD)
        {
            moveInput = 0f;

            if (Input.GetKey(KeyCode.RightArrow))
            {
                moveInput = 1f;
            }

            if (Input.GetKey(KeyCode.LeftArrow))
            {
                moveInput = -1f;
            }

            if (Input.GetKeyDown(KeyCode.UpArrow))
            {
                Jump();
            }

            if (Input.GetKeyDown(KeyCode.DownArrow))
            {
                Crouch();
            }
        }

        // Update walk/idle animation parameter for both keyboard and HUD buttons.
        if (animator != null)
        {
            animator.SetFloat("Speed", Mathf.Abs(moveInput));
        }

        // Flip the character sprite horizontally based on movement direction.
        if (spriteRenderer != null && moveInput != 0)
        {
            spriteRenderer.flipX = moveInput < 0;
        }
    }

    private void FixedUpdate()
    {
        // Apply horizontal movement while preserving vertical velocity.
        rb.linearVelocity = new Vector2(
            moveInput * moveSpeed,
            rb.linearVelocity.y
        );
    }

    public void SetMoveSpeed(float speed)
    {
        moveSpeed = speed;
    }

    // HUD movement controls.
    public void MoveRight()
    {
        usingHUD = true;
        moveInput = 1f;
    }

    public void MoveLeft()
    {
        usingHUD = true;
        moveInput = -1f;
    }

    public void StopMovement()
    {
        usingHUD = false;
        moveInput = 0f;
    }

    // Applies the jump force while preserving horizontal velocity.
    public void Jump()
    {
        bool canUseGroundJump = isGrounded || coyoteTimer > 0f;

        if (canUseGroundJump)
        {
            jumpCount = 1;
            coyoteTimer = 0f;
        }
        else
        {
            if (jumpCount >= maxJumps)
                return;

            jumpCount++;
        }

        rb.linearVelocity = new Vector2(
            rb.linearVelocity.x,
            jumpForce
        );

        // Trigger jump animation.
        if (animator != null)
        {
            animator.SetTrigger("Jump");
        }

        if (jumpClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(jumpClip);
        }
    }

    // HUD crouch action.
    public void Crouch()
    {
        Debug.Log("Crouch");

        // Trigger crouch animation.
        if (animator != null)
        {
            animator.SetTrigger("Crouch");
        }

        if (crouchClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(crouchClip);
        }
    }

    // Called when the Pickup HUD button is pressed.
    public void Pickup()
    {
        bool collectedSomething = false;

        if (TrashPickup.nearbyTrash != null)
        {
            TrashPickup.nearbyTrash.Collect();
            collectedSomething = true;
        }

        if (PurifierPickup.nearbyPurifier != null)
        {
            PurifierPickup.nearbyPurifier.Collect();
            collectedSomething = true;
        }

        // Play feedback only when an object was actually collected.
        if (!collectedSomething)
            return;

        if (animator != null)
        {
            animator.SetTrigger("Grab");
        }

        if (pickupClip != null && audioSource != null)
        {
            audioSource.PlayOneShot(pickupClip);
        }
    }
}